// Originally generated by `scripts/gen/wasm_simd.py`; now maintained by hand (the generator is out of date).
//! Scalar rung for [`super::auto_up`]: no SIMD, no token. Used when simd128
//! is neither compiled in nor switched on. Each formula is the wasm
//! instruction's lane semantics, so every rung gives the same result (NaN
//! payloads aside, which wasm leaves open). Lengths are checked by the
//! caller.

/// wasm `fmin`: NaN if either is NaN, `-0.0 < +0.0`.
fn wasm_fmin<T: Float>(x: T, y: T) -> T {
    if x.is_nan() || y.is_nan() {
        T::NAN
    } else if x == y {
        if x.is_sign_negative() { x } else { y }
    } else if x < y {
        x
    } else {
        y
    }
}

/// wasm `fmax`: NaN if either is NaN, `+0.0 > -0.0`.
fn wasm_fmax<T: Float>(x: T, y: T) -> T {
    if x.is_nan() || y.is_nan() {
        T::NAN
    } else if x == y {
        if x.is_sign_negative() { y } else { x }
    } else if x > y {
        x
    } else {
        y
    }
}

trait Float: Copy + PartialOrd {
    const NAN: Self;
    fn is_nan(self) -> bool;
    fn is_sign_negative(self) -> bool;
}

macro_rules! float {
	($($T:ty),*) => {$(
		impl Float for $T {
			const NAN: Self = <$T>::NAN;
			fn is_nan(self) -> bool {
				<$T>::is_nan(self)
			}
			fn is_sign_negative(self) -> bool {
				<$T>::is_sign_negative(self)
			}
		}
	)*};
}
float!(f32, f64);

/// Same grouping as `wasm_sum!`: lane `j` sums elements `j, j + L, ...`,
/// then the lanes left to right, all starting from the `+` identity.
fn sum_lanes<T: super::ops::macros::Lane, const L: usize>(a: &[T]) -> T {
    let mut acc = [T::SUM_ID; L];
    for (i, &x) in a.iter().enumerate() {
        acc[i % L] = acc[i % L].lane_add(x);
    }
    acc.iter().fold(T::SUM_ID, |s, &x| s.lane_add(x))
}

